 11	    public static void main(String[] args) {
 12	        assertMatches("finds repeated pattern matches",
 13	                "aaba", "aabaacaadaabaaba", List.of(0, 9, 12));
 14	        assertMatches("returns no matches when pattern is absent",
 15	                "xyz", "aabaacaadaabaaba", List.of());
 16	        assertMatches("returns no matches when pattern is longer than text",
 17	                "longpattern", "short", List.of());
 18	        assertMatches("supports empty patterns consistently",
 19	                "", "abc", List.of(0, 1, 2, 3));
 20	        assertEquals("joins match indexes for CLI output",
 21	                "0 9 12", NaivePatternSearch.joinMatchIndexes(List.of(0, 9, 12)));
 22	        assertSearchResult("search result keeps the originating request",
 23	                new SearchRequest("banana", "ana"), List.of(1, 3));
 24	        assertImmutability("search results expose an immutable match list",
 25	                new SearchRequest("aaaa", "aa"));
 26	        assertApplicationOutput("application formats the search output",
 27	                new SearchRequest("banana", "ana"), "1 3");
 28	        assertApplicationSearch("application returns the same search result contract",
 29	                new SearchRequest("banana", "ana"), List.of(1, 3));
 30	        assertFormatterOutput("formatter renders a search result",
 31	                new SearchRequest("banana", "ana"), "1 3");
 32	        assertSearchInput("uses CLI defaults when no arguments are provided",
 33	                new String[0], "aabaacaadaabaaba", "aaba");
 34	        assertSearchInput("allows overriding the text only",
 35	                new String[] {"banana"}, "banana", "aaba");
 36	        assertSearchInput("allows overriding both text and pattern",
 37	                new String[] {"banana", "ana"}, "banana", "ana");
 38	        assertCliOutput("cli support renders output from raw args",
 39	                new String[] {"banana", "ana"}, "1 3");
 40	    }
